import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { machineApi } from "../api/endpoints";
import { useAuth } from "../context/AuthContext";

const statusColors = {
  Running: "green",
  "Under Maintenance": "orange",
  Breakdown: "red",
  Idle: "gray",
};

export default function MachineList() {
  const { isOwner } = useAuth();
  const [machines, setMachines] = useState([]);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("");
  const [loading, setLoading] = useState(true);

  const loadMachines = () => {
    setLoading(true);
    machineApi
      .list({ search, status })
      .then((res) => setMachines(res.data.data))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    const timeout = setTimeout(loadMachines, 300); // debounce search
    return () => clearTimeout(timeout);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, status]);

  return (
    <div>
      <div className="page-header">
        <h1>{isOwner ? "Machines" : "My Assigned Machines"}</h1>
        {isOwner && (
          <Link to="/machines/new" className="btn-primary">
            + Add Machine
          </Link>
        )}
      </div>

      <div className="filter-bar">
        <input
          placeholder="Search by name or number..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="">All Statuses</option>
          <option value="Running">Running</option>
          <option value="Under Maintenance">Under Maintenance</option>
          <option value="Breakdown">Breakdown</option>
          <option value="Idle">Idle</option>
        </select>
      </div>

      {loading ? (
        <div>Loading...</div>
      ) : (
        <div className="card-grid">
          {machines.map((m) => (
            <Link to={`/machines/${m._id}`} key={m._id} className="machine-card">
              <div className="machine-card-header">
                <h3>{m.machineName}</h3>
                <span className={`status-badge ${statusColors[m.status]}`}>{m.status}</span>
              </div>
              <p>{m.machineNumber}</p>
              <p className="muted">{m.machineType}</p>
            </Link>
          ))}
          {machines.length === 0 && <p>No machines found.</p>}
        </div>
      )}
    </div>
  );
}
